  int get hashCode => key.hashCode ^ value.hashCode;

  @override
  bool operator ==(Object other) =>
      identical(this, other) ||
      other is BridgeMetadataField &&
          runtimeType == other.runtimeType &&
          key == other.key &&
          value == other.value;
}
